function withHeaders(response) {
  const headers = new Headers(response.headers);
  headers.set("tdm-reservation", "1");
  headers.set("tdm-policy", "https://itcop.org/licence/0pn-mrt-1.0.json");
  headers.set("Access-Control-Allow-Origin", "https://itcop.org");
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers
  });
}

function buildReceipt(noticeVersionReference) {
  const hex16 = Array.from(crypto.getRandomValues(new Uint8Array(8))).map((byte) => byte.toString(16).padStart(2, "0")).join("");
  return {
    receipt_schema: "ancr-notice-receipt-2.0",
    receipt_id: "urn:ancr:receipt:" + hex16,
    scope_of_work: "Clean AI Receipts report access",
    controller_identification_record_id: "crdi:uk:0pn:tcieg",
    notice_version_reference: noticeVersionReference || "0pn-mrt-1.0-2026-08-31",
    presented_at: new Date().toISOString(),
    data_authority: {
      published_work: {
        licence: "https://creativecommons.org/licenses/by/4.0/",
        terms_version_reference: "0pn-mrt-1.0-2026-08-31"
      }
    },
    evidence_request_endpoint: "https://itcop.org/reuse/evidence",
    anonymous_request_permitted: true,
    demo: true
  };
}

export default {
  async fetch(request) {
    const url = new URL(request.url);

    if (request.method === "OPTIONS") {
      return withHeaders(
        new Response(null, {
          status: 204,
          headers: {
            "Access-Control-Allow-Methods": "POST, OPTIONS",
            "Access-Control-Allow-Headers": "Content-Type"
          }
        })
      );
    }

    if (request.method === "POST" && url.pathname === "/paper/read") {
      let body;

      try {
        body = await request.json();
      } catch {
        body = null;
      }

      if (!body || typeof body !== "object" || Array.isArray(body) || body.notice_acknowledged !== true) {
        return withHeaders(
          Response.json(
            { error: "Acknowledge the notice to receive the report." },
            { status: 400 }
          )
        );
      }

      const receipt = buildReceipt(body.notice_version_reference);
      return withHeaders(
        Response.json({ receipt, filename: "TCIEG_Clean_AI_Receipts_External_Review_v0.1.pdf", pdf_base64: PDF_B64 })
      );
    }

    return withHeaders(
      new Response(
        "Complete and acknowledge the notice to receive the report. See https://itcop.org/paper/",
        { status: 403 }
      )
    );
  }
};
